CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS departments (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT UNIQUE, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS positions (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employee_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employment_types (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employees (
 id INTEGER PRIMARY KEY AUTOINCREMENT, employee_no TEXT UNIQUE NOT NULL, first_name TEXT NOT NULL, middle_name TEXT, last_name TEXT NOT NULL, email TEXT,
 department_id INTEGER, position_id INTEGER, category_id INTEGER, employment_type_id INTEGER, date_hired TEXT, employment_status TEXT DEFAULT 'active', archived_at TEXT,
 created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(position_id) REFERENCES positions(id), FOREIGN KEY(category_id) REFERENCES employee_categories(id), FOREIGN KEY(employment_type_id) REFERENCES employment_types(id));
CREATE TABLE IF NOT EXISTS users (
 id INTEGER PRIMARY KEY AUTOINCREMENT, role_id INTEGER NOT NULL, employee_id INTEGER, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, status TEXT DEFAULT 'active', last_login_at TEXT,
 created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS employee_separations (id INTEGER PRIMARY KEY AUTOINCREMENT, employee_id INTEGER NOT NULL, separation_date TEXT NOT NULL, separation_type TEXT NOT NULL, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS hrm_factors (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, description TEXT, display_order INTEGER DEFAULT 0, status TEXT DEFAULT 'active', is_outcome INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assessment_periods (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, start_date TEXT, end_date TEXT, status TEXT DEFAULT 'draft', scale_min INTEGER DEFAULT 1, scale_max INTEGER DEFAULT 4, scale_labels TEXT DEFAULT '1=Strongly Disagree|2=Disagree|3=Agree|4=Strongly Agree', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS survey_questions (id INTEGER PRIMARY KEY AUTOINCREMENT, period_id INTEGER NOT NULL, factor_id INTEGER NOT NULL, question_text TEXT NOT NULL, display_order INTEGER DEFAULT 0, is_required INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(period_id) REFERENCES assessment_periods(id), FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS survey_participation (id INTEGER PRIMARY KEY AUTOINCREMENT, period_id INTEGER NOT NULL, employee_id INTEGER NOT NULL, completed_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(period_id,employee_id), FOREIGN KEY(period_id) REFERENCES assessment_periods(id), FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS survey_responses (id INTEGER PRIMARY KEY AUTOINCREMENT, period_id INTEGER NOT NULL, submitted_at TEXT DEFAULT CURRENT_TIMESTAMP, snapshot_department_id INTEGER, snapshot_category_id INTEGER, snapshot_employment_type_id INTEGER, FOREIGN KEY(period_id) REFERENCES assessment_periods(id));
CREATE TABLE IF NOT EXISTS survey_response_items (id INTEGER PRIMARY KEY AUTOINCREMENT, response_id INTEGER NOT NULL, question_id INTEGER NOT NULL, response_value INTEGER NOT NULL, FOREIGN KEY(response_id) REFERENCES survey_responses(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES survey_questions(id));
CREATE TABLE IF NOT EXISTS feedback_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, factor_id INTEGER, status TEXT DEFAULT 'active', FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS feedback_themes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, status TEXT DEFAULT 'active');
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, period_id INTEGER, category_id INTEGER, body TEXT NOT NULL, is_anonymous INTEGER DEFAULT 1, submitter_employee_id INTEGER, snapshot_department_id INTEGER, review_status TEXT DEFAULT 'new', created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(period_id) REFERENCES assessment_periods(id), FOREIGN KEY(category_id) REFERENCES feedback_categories(id), FOREIGN KEY(submitter_employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS feedback_theme_links (feedback_id INTEGER NOT NULL, theme_id INTEGER NOT NULL, PRIMARY KEY(feedback_id,theme_id), FOREIGN KEY(feedback_id) REFERENCES feedback(id) ON DELETE CASCADE, FOREIGN KEY(theme_id) REFERENCES feedback_themes(id));
CREATE TABLE IF NOT EXISTS research_baselines (id INTEGER PRIMARY KEY AUTOINCREMENT, factor_id INTEGER, metric_key TEXT NOT NULL, value REAL NOT NULL, source TEXT, study_label TEXT, FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS retention_driver_models (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, source TEXT, is_baseline INTEGER DEFAULT 1, valid_from TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS retention_driver_coefficients (id INTEGER PRIMARY KEY AUTOINCREMENT, model_id INTEGER NOT NULL, factor_id INTEGER NOT NULL, coefficient REAL NOT NULL, coefficient_type TEXT DEFAULT 'beta', FOREIGN KEY(model_id) REFERENCES retention_driver_models(id), FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS action_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS decision_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, threshold_low REAL, threshold_high REAL, stability_band REAL DEFAULT 0.10, resulting_category TEXT, active INTEGER DEFAULT 1, is_prototype INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS priority_areas (id INTEGER PRIMARY KEY AUTOINCREMENT, period_id INTEGER NOT NULL, factor_id INTEGER NOT NULL, department_id INTEGER, current_score REAL, previous_score REAL, trend TEXT, priority_level TEXT, action_category TEXT, theme_count INTEGER DEFAULT 0, suggested_recommendation TEXT, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(period_id,factor_id,department_id), FOREIGN KEY(period_id) REFERENCES assessment_periods(id), FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS recommendation_library (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recommendation_factors (recommendation_id INTEGER NOT NULL, factor_id INTEGER NOT NULL, PRIMARY KEY(recommendation_id,factor_id), FOREIGN KEY(recommendation_id) REFERENCES recommendation_library(id) ON DELETE CASCADE, FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS interventions (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, factor_id INTEGER, priority_area_id INTEGER, recommendation_id INTEGER, issue TEXT, description TEXT, objective TEXT, responsible_department_id INTEGER, responsible_user_id INTEGER, start_date TEXT, target_date TEXT, budget_amount REAL DEFAULT 0, expected_outcome TEXT, notes TEXT, status TEXT DEFAULT 'Planned', approval_status TEXT DEFAULT 'Pending', approved_by INTEGER, approved_at TEXT, approval_notes TEXT, is_public INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(factor_id) REFERENCES hrm_factors(id), FOREIGN KEY(priority_area_id) REFERENCES priority_areas(id), FOREIGN KEY(recommendation_id) REFERENCES recommendation_library(id), FOREIGN KEY(responsible_department_id) REFERENCES departments(id), FOREIGN KEY(responsible_user_id) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS intervention_updates (id INTEGER PRIMARY KEY AUTOINCREMENT, intervention_id INTEGER NOT NULL, user_id INTEGER NOT NULL, status TEXT, note TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(intervention_id) REFERENCES interventions(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS intervention_evaluations (id INTEGER PRIMARY KEY AUTOINCREMENT, intervention_id INTEGER NOT NULL, factor_id INTEGER NOT NULL, before_period_id INTEGER NOT NULL, after_period_id INTEGER NOT NULL, before_score REAL, after_score REAL, difference REAL, result_label TEXT, evaluator_note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(intervention_id) REFERENCES interventions(id), FOREIGN KEY(factor_id) REFERENCES hrm_factors(id));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, action TEXT NOT NULL, entity TEXT, entity_id INTEGER, summary TEXT, ip_address TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_settings (id INTEGER PRIMARY KEY AUTOINCREMENT, key_name TEXT UNIQUE NOT NULL, value TEXT, updated_by INTEGER, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sri_response ON survey_response_items(response_id);
CREATE INDEX IF NOT EXISTS idx_sr_period_dept ON survey_responses(period_id,snapshot_department_id);
CREATE INDEX IF NOT EXISTS idx_sq_period_factor ON survey_questions(period_id,factor_id);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);